import{_ as s,H as n,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"热点加餐｜Harness 架构深度解析","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是 Harness？","slug":"什么是-harness","link":"#什么是-harness","children":[]},{"level":2,"title":"Agentic Loop——Harness 的心脏","slug":"agentic-loop——harness-的心脏","link":"#agentic-loop——harness-的心脏","children":[]},{"level":2,"title":"内置工具——Harness 的手脚","slug":"内置工具——harness-的手脚","link":"#内置工具——harness-的手脚","children":[]},{"level":2,"title":"上下文管理——被忽视的关键能力","slug":"上下文管理——被忽视的关键能力","link":"#上下文管理——被忽视的关键能力","children":[]},{"level":2,"title":"开源还是闭源？一个被误解的事实","slug":"开源还是闭源-一个被误解的事实","link":"#开源还是闭源-一个被误解的事实","children":[]},{"level":2,"title":"Claude Agent SDK——可编程的 Harness","slug":"claude-agent-sdk——可编程的-harness","link":"#claude-agent-sdk——可编程的-harness","children":[]},{"level":2,"title":"第三方 Harness 的崛起与冲突","slug":"第三方-harness-的崛起与冲突","link":"#第三方-harness-的崛起与冲突","children":[]},{"level":2,"title":"为什么 2026 年是 Harness 之年？","slug":"为什么-2026-年是-harness-之年","link":"#为什么-2026-年是-harness-之年","children":[]},{"level":2,"title":"动手验证：感受 Harness 的存在","slug":"动手验证-感受-harness-的存在","link":"#动手验证-感受-harness-的存在","children":[]},{"level":2,"title":"总结一下","slug":"总结一下","link":"#总结一下","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"参考资料","slug":"参考资料","link":"#参考资料","children":[{"level":3,"title":"Tier 1：AI 实验室一手资料","slug":"tier-1-ai-实验室一手资料","link":"#tier-1-ai-实验室一手资料","children":[]},{"level":3,"title":"Tier 2: 学术论文","slug":"tier-2-学术论文","link":"#tier-2-学术论文","children":[]},{"level":3,"title":"Tier 3: 行业内高影响力文章","slug":"tier-3-行业内高影响力文章","link":"#tier-3-行业内高影响力文章","children":[]}]}],"relativePath":"ClaudeCode工程化实战/热点加餐｜Harness架构深度解析.md","filePath":"ClaudeCode工程化实战/热点加餐｜Harness架构深度解析.md","lastUpdated":1779815462000}'),r={name:"ClaudeCode工程化实战/热点加餐｜Harness架构深度解析.md"};function i(o,e,l,p,g,d){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="热点加餐-harness-架构深度解析" tabindex="-1">热点加餐｜Harness 架构深度解析 <a class="header-anchor" href="#热点加餐-harness-架构深度解析" aria-label="Permalink to &quot;热点加餐｜Harness 架构深度解析&quot;">​</a></h1><p>你好，我是黄佳。</p><p>在我们的专栏上线初期，就有学员问过我：黄老师，你一直说Claude Code最懂工程，你为什么这么说？这个问题和另外一个群里面经常被问到的问题其实几乎等价，就是 Claude Code 为什么强，究竟强在哪里？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/ffdb56816e44d3bc1088040a7e08dc11.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/ffdb56816e44d3bc1088040a7e08dc11.jpg" alt=""></a></p><p>至今为止，我们一直在 Claude Code 里面折腾——写 CLAUDE.md、配 Skills、调 Hooks、连 MCP。但倒是尚未正面思考过一个更根本的问题： <strong>Claude Code 本身是什么？</strong></p><p>它不是 Claude 模型。模型是 Anthropic 的 API，任何人都可以调用。它也不是一个简单的命令行工具——如果是，为什么同一个 Claude Sonnet 模型，通过 API 直接调用和通过 Claude Code 调用，表现差距那么大？</p><p>答案藏在一个词里：Harness。</p><h2 id="什么是-harness" tabindex="-1">什么是 Harness？ <a class="header-anchor" href="#什么是-harness" aria-label="Permalink to &quot;什么是 Harness？&quot;">​</a></h2><p>先看 Anthropic 官方文档里是怎么说的：</p><blockquote><p>Claude Code serves as the <strong>agentic harness</strong> around Claude: it provides the tools, context management, and execution environment that turn a language model into a capable coding agent.</p></blockquote><p>翻译一下，Claude Code 是一个 <strong>智能体编排框架</strong>，包裹在 Claude 模型外面。它提供工具、上下文管理和执行环境，把一个语言模型变成一个有能力的编码 Agent。</p><p>注意，这个定义里有三个关键词， <strong>工具</strong>、 <strong>上下文管理</strong>、 <strong>执行环境</strong>。模型本身只会生成文本。是 Harness 给了它读文件的能力、写代码的能力、搜索代码库的能力、在终端执行命令的能力。没有 Harness，Claude 就是一个只会说话的大脑——有智力，没有手脚。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/5c73e5d6313819828d739eeb2bfca72b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/5c73e5d6313819828d739eeb2bfca72b.png" alt="图片"></a></p><p>业界对Harness的核心共识是：</p><blockquote><p><strong>Agent Harness</strong> = 包裹 LLM 的运行时基础设施，管理工具调度、上下文工程、安全执行、状态持久化和会话连续性。LLM 只负责推理决策。</p><p>2026 年的关键洞察： <strong>竞争差异化的重心已从 Model 转移到 Harness</strong>。</p></blockquote><p>下面这张图，把 Harness 的内部结构拆得很清楚。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/9697d298c3132c33e94c6b2eac1e1eaf.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/9697d298c3132c33e94c6b2eac1e1eaf.png" alt="图片"></a></p><p><strong>Agent = Model + Harness。</strong> 图中最核心的位置是 <strong>Model</strong>——那个蓝色芯片图标，代表 Claude 的大语言模型。但模型本身只是一个推理引擎，它不能独立行动。</p><p>真正让它变成 Agent 的，是包裹在它周围的五个 Harness 组件。</p><ul><li><p><strong>Tools（工具）</strong>，模型的手脚。Read、Write、Edit、Bash、Grep……这些工具赋予模型与文件系统、终端、网络交互的能力。没有工具，模型只能说，不能做。</p></li><li><p><strong>Context（上下文）</strong>，模型的记忆加载器。CLAUDE.md、系统提示词、对话历史、工具定义——这些上下文在每一轮循环中被注入模型，决定了模型看到什么、知道什么。上下文管理的精妙之处是，它不仅是被动的信息传递，还包括主动的压缩和重注入策略。</p></li><li><p><strong>Memory（记忆）</strong>，模型的长期存储。跨会话的记忆持久化，让模型能“记住”你的偏好、项目规则和历史决策。CLAUDE.md 是显式记忆，自动记忆（ <code>~/.claude/memory/</code>）是隐式记忆。没有 Memory，每次对话都从零开始。</p></li><li><p><strong>Hooks（钩子）</strong>，模型的神经反射。事件驱动的自动化机制，在工具执行前后触发自定义逻辑。比如每次保存文件前自动格式化，每次提交前自动运行 lint。Hooks 让 Harness 有了“条件反射”的能力——不需要模型主动决策，某些行为会自动发生。</p></li><li><p><strong>Permissions（权限）</strong>——模型的安全围栏。哪些工具可以自由使用，哪些需要人工审批，哪些完全禁止——权限系统是 Harness 的安全底线。它解决了一个核心矛盾：你希望 Agent 足够自主以提高效率，但又不希望它自主到失控。</p></li></ul><p>注意图中的空间关系： <strong>Model 在中心，五个组件围绕它排列，整体被一个名为 Harness 的边框包裹</strong>。这不是随意的布局，它精确表达了一个架构事实：模型不直接接触外部世界，所有交互都通过 Harness 的组件中转。Harness 是模型和现实之间的 <strong>唯一接口</strong>。</p><p>这五个组件也不是孤立的。Tools 的执行结果变成 Context 的一部分；Hooks 在 Tools 执行前后触发；Permissions 决定哪些 Tools 可以被调用；Memory 用于跨会话保留 Context 中的关键信息。它们构成了一个协同运转的系统，少了任何一个，Agent 的能力都会大打折扣。</p><p>我们再看看 Harness 在整个系统中的层级位置，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/20ffc62d48e79a3f7beaee728bb21bb9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/20ffc62d48e79a3f7beaee728bb21bb9.jpg" alt=""></a></p><h2 id="agentic-loop——harness-的心脏" tabindex="-1">Agentic Loop——Harness 的心脏 <a class="header-anchor" href="#agentic-loop——harness-的心脏" aria-label="Permalink to &quot;Agentic Loop——Harness 的心脏&quot;">​</a></h2><p>如果 Harness 是一台机器，Agentic Loop 就是它的发动机。整个 Claude Code 的运转，归根到底就是一个循环：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/228da3c3689802fea8a444dab5a8aedd.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/228da3c3689802fea8a444dab5a8aedd.jpg" alt=""></a></p><p>关键点在于 <strong>步骤 ② 和步骤 ④ 之间的循环</strong>。模型不是一次性给出最终答案的。它可能先读一个文件，看完结果后决定再搜索一下，搜索完又决定编辑某行代码，编辑完再运行测试——每一步都是一次循环。一个复杂任务可能跑几十轮循环。</p><p>循环什么时候结束？满足下面两个条件之一即可：</p><ol><li><p><strong>模型主动停止</strong>——Claude 认为任务完成，生成纯文本回复，不再请求工具调用。API 返回 <code>stop_reason: &quot;end_turn&quot;</code>。</p></li><li><p><strong>达到最大轮次</strong>——Harness 设置了 <code>--max-turns</code> 限制，防止无限循环。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/f21f999547a2b8e10902cedc0c02ab1a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/f21f999547a2b8e10902cedc0c02ab1a.jpg" alt=""></a></p><h2 id="内置工具——harness-的手脚" tabindex="-1">内置工具——Harness 的手脚 <a class="header-anchor" href="#内置工具——harness-的手脚" aria-label="Permalink to &quot;内置工具——Harness 的手脚&quot;">​</a></h2><p>Agentic Loop 是引擎，工具是车轮。Claude Code 内置了 20+ 个左右的工具，覆盖了软件工程的五个原子操作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/324bce7fab41de545bb1628cfa68b3e5.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/324bce7fab41de545bb1628cfa68b3e5.jpg" alt=""></a></p><p>工具设计背后有一个深刻的哲学， <strong>少而精</strong>。Claude Code 没有内置重构工具、测试工具、部署工具……它只给了最基础的原语。重构是 Read + Edit + Bash 的组合涌现；测试是 Bash + Read 的组合涌现；部署还是 Bash。</p><p>这就像计算机只需要几条指令就能图灵完备一样。Harness 不需要为每种场景造一个工具，它只需要确保 <strong>基础工具的组合空间足够大</strong>。</p><p>但 Bash 是个例外。Bash 工具是一个 <strong>图灵完备的逃逸舱</strong>。通过它，Claude 可以执行任何 Shell 命令：安装依赖、运行测试、调用 API、操作数据库。这意味着 Claude Code 的能力上限，理论上等于操作系统的能力上限。</p><p>这也是为什么 Harness 需要 <strong>权限控制</strong> 的原因。</p><h2 id="上下文管理——被忽视的关键能力" tabindex="-1">上下文管理——被忽视的关键能力 <a class="header-anchor" href="#上下文管理——被忽视的关键能力" aria-label="Permalink to &quot;上下文管理——被忽视的关键能力&quot;">​</a></h2><p>大多数人讨论 Agent 框架时，只关心工具和循环。但 Harness 最精巧的部分，其实是 <strong>上下文管理</strong>。</p><p>Claude 的上下文窗口是有限的（200K tokens）。一个真实的编码任务——读 20 个文件、搜索 50 次、执行 30 条命令——产生的对话历史会迅速膨胀到几十万 tokens。如果不管理，要么爆掉上下文窗口，要么模型开始“遗忘”早期信息。</p><p>Claude Code 的解决方案是 <strong>自动压缩</strong>。当对话历史接近上下文窗口的 92% 时，Harness 会触发一次压缩操作：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对话历史（180K tokens）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼ 压缩触发</span></span>
<span class="line"><span>┌────────────────────────────┐</span></span>
<span class="line"><span>│ 保留：最近的消息（完整）      │</span></span>
<span class="line"><span>│ 压缩：早期消息 → 摘要        │</span></span>
<span class="line"><span>│ 重注入：CLAUDE.md 内容       │</span></span>
<span class="line"><span>│ 重注入：系统提示词            │</span></span>
<span class="line"><span>│ 重注入：工具定义              │</span></span>
<span class="line"><span>└────────────────────────────┘</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>压缩后对话历史（~80K tokens）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼ 继续工作</span></span></code></pre></div><p>注意最后三行， <strong>CLAUDE.md、系统提示词、工具定义在每次压缩后都会重新注入</strong>。这意味着即使对话历史被截断了，模型仍然知道项目的规则、自己有哪些工具、应该遵循什么约定。</p><p>这就是为什么你在 CLAUDE.md 里写的东西那么“持久”——不是因为模型记住了它，而是 Harness 在每次压缩后都重新塞给模型。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/d90e049607fe7ed255f76cfce612133c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/d90e049607fe7ed255f76cfce612133c.jpg" alt=""></a></p><h2 id="开源还是闭源-一个被误解的事实" tabindex="-1">开源还是闭源？一个被误解的事实 <a class="header-anchor" href="#开源还是闭源-一个被误解的事实" aria-label="Permalink to &quot;开源还是闭源？一个被误解的事实&quot;">​</a></h2><p>很多人以为 Claude Code 是开源的。毕竟它在 GitHub 上有一个仓库（ <code>github.com/anthropics/claude-code</code>），截至 2026 年 3 月已有 81K+ stars。</p><p>但打开仓库的 LICENSE 文件，你会看到：</p><blockquote><p>© Anthropic PBC. All rights reserved. Use is subject to Anthropic’s Commercial Terms of Service.</p></blockquote><p>其实 <strong>Claude Code 不是开源软件。</strong> 它是专有软件。</p><p>GitHub 仓库里有什么？安装脚本、插件模板、GitHub Action、文档、示例配置。核心的 Agentic Loop、工具执行引擎、上下文管理器——这些 Harness 的核心代码——以编译后的 npm 包（ <code>@anthropic-ai/claude-code</code>）分发，源码并不可见。</p><p>2026 年 1 月，GitHub 上出现了一个 issue（#22002），请求 Anthropic 将 Claude Code CLI 以 Apache 2.0 或 MIT 许可证开源。截至目前，这个 issue 仍然是“Open”状态。</p><h2 id="claude-agent-sdk——可编程的-harness" tabindex="-1">Claude Agent SDK——可编程的 Harness <a class="header-anchor" href="#claude-agent-sdk——可编程的-harness" aria-label="Permalink to &quot;Claude Agent SDK——可编程的 Harness&quot;">​</a></h2><p>虽然 Claude Code CLI 本身不开源，但 Anthropic 在 2025 年发布了 <strong>Claude Agent SDK</strong>——一套可编程的 Harness 接口。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># TypeScript 版本</span></span>
<span class="line"><span>npm install &amp;#64;anthropic-ai/claude-agent-sdk</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Python 版本</span></span>
<span class="line"><span>pip install claude-agent-sdk</span></span></code></pre></div><p>Agent SDK 提供了与 Claude Code 完全相同的 Agentic Loop、内置工具、上下文管理、权限系统、Hooks、Sub-Agent 支持和 MCP 集成。区别在于，Claude Code 是面向终端用户的交互式产品，Agent SDK 是面向开发者的编程库。</p><p>用 Agent SDK，你可以构建自己的 Harness——一个定制化的 Agent 应用，嵌入到你自己的产品、工作流或 CI/CD 系统中。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from claude_agent_sdk import AgentClient</span></span>
<span class="line"><span></span></span>
<span class="line"><span>client = AgentClient(api_key=&quot;...&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 创建一个有工具能力的 Agent</span></span>
<span class="line"><span>result = client.run(</span></span>
<span class="line"><span>    prompt=&quot;审查这个 PR 的安全问题&quot;,</span></span>
<span class="line"><span>    tools=[&quot;Read&quot;, &quot;Grep&quot;, &quot;Glob&quot;, &quot;Bash&quot;],</span></span>
<span class="line"><span>    max_turns=20,</span></span>
<span class="line"><span>    allowed_tools={&quot;Bash&quot;: [&quot;npm test&quot;, &quot;npm run lint&quot;]}</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(result.text)</span></span></code></pre></div><p>如果说 Claude Code 是一辆出厂配置的整车，Agent SDK 就是发动机总成——你可以把它装进任何车身里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/77e226d6dff0bb380efd5e98bfd33a98.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/77e226d6dff0bb380efd5e98bfd33a98.jpg" alt=""></a></p><h2 id="第三方-harness-的崛起与冲突" tabindex="-1">第三方 Harness 的崛起与冲突 <a class="header-anchor" href="#第三方-harness-的崛起与冲突" aria-label="Permalink to &quot;第三方 Harness 的崛起与冲突&quot;">​</a></h2><p>Claude Code 的成功证明了一件事： <strong>模型 + Harness = 10× 生产力</strong>。这个公式吸引了大量第三方工具来构建自己的 Harness。</p><p><strong>OpenCode</strong>（前身 SST）是最成功的第三方 Harness。它用 Client-Server 架构解决了 Claude Code 的“单表面”局限——TUI、桌面 App、IDE 插件、Slack 机器人共享同一个后端。截至 2026 年 3 月，OpenCode 拿到了 119K GitHub stars，月活 65 万+，超过了 Claude Code 本身的 star 数。</p><p>但 2026 年 1 月，Anthropic 采取了一个争议性举措： <strong>封堵了第三方工具通过消费者 OAuth Token 调用 Claude API 的通道</strong>。这直接影响了 OpenCode、Cursor、Windsurf 等工具的用户——他们之前可以用 Claude Pro 订阅的 Token 在这些第三方工具里使用 Claude，封堵后必须购买独立的 API Key。</p><p>这件事引发了开发者社区的强烈反弹，但也揭示了 Harness 生态的核心张力： <strong>模型提供商希望控制 Harness 层，因为 Harness 决定了 API 调用量和用户体验；第三方 Harness 希望模型层是可替换的商品，因为这样它们才能建立独立的价值。</strong></p><p>我为你梳理一下当前的 Harness 生态格局（截止到2026年3月31日）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/cdd4ef680af1b1d796c723ee762f6556.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/958033/cdd4ef680af1b1d796c723ee762f6556.jpg" alt=""></a></p><h2 id="为什么-2026-年是-harness-之年" tabindex="-1">为什么 2026 年是 Harness 之年？ <a class="header-anchor" href="#为什么-2026-年是-harness-之年" aria-label="Permalink to &quot;为什么 2026 年是 Harness 之年？&quot;">​</a></h2><p>2025 年的关键词是 Agent。2026 年的关键词是 <strong>Agent Harness</strong>。</p><p>为什么？因为行业已经意识到。模型本身正在商品化——Claude、GPT、Gemini、DeepSeek 的能力差距在缩小。但 <strong>同一个模型在不同 Harness 中的表现差距，远大于不同模型在同一个 Harness 中的差距</strong>。</p><p>换句话说，Harness 比模型更重要。</p><p>这不是我的臆断。有几个数据点足以佐证：</p><ul><li><p>Claude Code 在 2025 年 11 月达到 <strong>10 亿美元年化收入</strong>——这是一个 Harness 产品的收入，不是模型本身的收入。</p></li><li><p>Anthropic 在 2026 年 3 月收购了 <strong>Bun</strong>（JavaScript 运行时），明确表示要加强 Claude Code 的基础设施。收购一个运行时来加强一个 Harness——这说明 Anthropic 把 Harness 视为战略级资产。</p></li><li><p>开源社区出现了“Agent Harness“作为独立品类。GitHub 上以 “harness” 为关键词的新仓库数量在 2026 年 Q1 翻了三倍。</p></li></ul><p>对于我们开发者来说，这意味着什么？</p><p><strong>理解 Harness 比理解模型更重要。</strong></p><p>模型的能力由 Anthropic/OpenAI 决定，你无法改变。但 Harness 的配置——CLAUDE.md 怎么写、工具权限怎么设、Hooks 怎么接、MCP 怎么连——这些全在你手中。你前面学的每一讲，本质上都是在 <strong>调教 Harness</strong>。</p><h2 id="动手验证-感受-harness-的存在" tabindex="-1">动手验证：感受 Harness 的存在 <a class="header-anchor" href="#动手验证-感受-harness-的存在" aria-label="Permalink to &quot;动手验证：感受 Harness 的存在&quot;">​</a></h2><p>最后来一个非常简单的实验，只是感受 Harness 的作用（其实我们每天都在感受着这种不同）。</p><p>用裸 API 和 Claude Code 分别执行同一个任务：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 方式一：裸 API 调用（没有 Harness）- 你可以换成Deepseek或GPT等任何模型</span></span>
<span class="line"><span>curl https://api.anthropic.com/v1/messages \\</span></span>
<span class="line"><span>  -H &quot;x-api-key: $ANTHROPIC_API_KEY&quot; \\</span></span>
<span class="line"><span>  -H &quot;content-type: application/json&quot; \\</span></span>
<span class="line"><span>  -H &quot;anthropic-version: 2023-06-01&quot; \\</span></span>
<span class="line"><span>  -d &#39;{</span></span>
<span class="line"><span>    &quot;model&quot;: &quot;claude-sonnet-4-6-20260320&quot;,</span></span>
<span class="line"><span>    &quot;max_tokens&quot;: 1024,</span></span>
<span class="line"><span>    &quot;messages&quot;: [{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;找出当前目录下所有 TODO 注释并列出文件名和行号&quot;}]</span></span>
<span class="line"><span>  }&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 方式二：通过 Harness（Claude Code）</span></span>
<span class="line"><span>claude -p &quot;找出当前目录下所有 TODO 注释并列出文件名和行号&quot; --output-format text</span></span></code></pre></div><p>裸 API 会怎么回答？它会告诉你“你可以用 grep 命令来搜索”——因为它没有手脚，只能 <strong>说</strong>。</p><p>Claude Code 会怎么做？它会直接执行 <code>Grep</code> 工具搜索 TODO，然后返回完整的文件名、行号和上下文——因为 Harness 给了它 <strong>行动</strong> 的能力。</p><p>同一个大脑，有没有 Harness，结果天壤之别。</p><h2 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to &quot;总结一下&quot;">​</a></h2><p>这一讲我们从底层理解了 Claude Code 的真实身份——它是一个 <strong>Harness</strong>，一个包裹在 Claude 模型外面的智能体编排框架。</p><p>我们再回顾一下核心要点。</p><ol><li><p><strong>Harness = 工具 + 上下文管理 + 执行环境 + 权限控制</strong>。它把模型的智力转化为行动力。</p></li><li><p><strong>Agentic Loop 是 Harness 的心脏</strong>。“推理 → 工具调用 → 结果回注 → 继续推理”的循环是所有复杂行为的涌现基础。</p></li><li><p><strong>20+个内置工具覆盖 5 个原子操作</strong>（读、写、执行、联网、编排）。少而精的设计让组合空间最大化。</p></li><li><p><strong>上下文管理是被低估的关键能力</strong>。自动压缩 + CLAUDE.md 重注入，确保模型在长任务中不丢失关键信息。</p></li><li><p><strong>Claude Code 不是开源软件</strong>。核心 Harness 代码以编译后的 npm 包分发。Agent SDK 提供了可编程的 Harness 接口。</p></li><li><p><strong>2026 年是 Harness 之年</strong>。同一模型在不同 Harness 中的表现差距，大于不同模型在同一 Harness 中的差距。因此理解 Harness 比理解模型更重要。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>1.如果你要为自己的团队构建一个定制化的 Harness（比如专门用于数据分析），你会保留 Claude Code 的哪些内置工具，去掉哪些，新增哪些？为什么？</p><p>2.Claude Code 的上下文压缩策略“摘要早期消息 + 重注入 CLAUDE.md”。你能想到这种策略的局限性吗？在什么场景下会出问题？</p><p>3.从商业角度看，Anthropic 选择“开放 Agent SDK、封闭 Claude Code CLI” 的策略是否合理？如果你是 Anthropic 的竞争对手，你会怎么应对？</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>我好多次和大伙儿强调一手资料的重要性，加餐梳理之外，我也想把 Harness 主题下，我认为非常有价值的参考资料分享给你。</p><h3 id="tier-1-ai-实验室一手资料" tabindex="-1">Tier 1：AI 实验室一手资料 <a class="header-anchor" href="#tier-1-ai-实验室一手资料" aria-label="Permalink to &quot;Tier 1：AI 实验室一手资料&quot;">​</a></h3><p><strong>Anthropic</strong></p><ul><li><p><a href="https://www.anthropic.com/engineering/effective-harnesses-for-long-running-agents" target="_blank" rel="noreferrer">Effective Harnesses for Long-Running Agents</a>：官方定义 harness 架构，Initializer + Coding Agent 两阶段设计。</p></li><li><p><a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">Building Effective Agents</a>：2024.12 发表的行业奠基性文章，Workflow vs Agent 区分，Harness 概念前身。</p></li><li><p><a href="https://www.anthropic.com/engineering/building-agents-with-the-claude-agent-sdk" target="_blank" rel="noreferrer">Building Agents with the Claude Agent SDK</a>：Agent SDK 官方文档，暴露 Claude Code 内部的 Agent Loop。</p></li></ul><p><strong>OpenAI</strong></p><ul><li><p><a href="https://openai.com/index/harness-engineering/" target="_blank" rel="noreferrer">Harness Engineering</a>：2026.2，正式提出 “harness engineering” 概念，~1500 自动化 PR。</p></li><li><p><a href="https://openai.com/index/unrolling-the-codex-agent-loop/" target="_blank" rel="noreferrer">Unrolling the Codex Agent Loop</a>：Codex CLI agent loop 详解。</p></li><li><p><a href="https://openai.com/index/unlocking-the-codex-harness/" target="_blank" rel="noreferrer">Unlocking the Codex Harness</a>：Codex harness 的 App Server 层实现。</p></li></ul><h3 id="tier-2-学术论文" tabindex="-1">Tier 2: 学术论文 <a class="header-anchor" href="#tier-2-学术论文" aria-label="Permalink to &quot;Tier 2: 学术论文&quot;">​</a></h3><p><a href="https://arxiv.org/abs/2603.05344" target="_blank" rel="noreferrer">Building Effective AI Coding Agents</a>（arXiv 2603.05344），这篇论文是学术界对 Harness 概念的首次严肃形式化——scaffolding vs harness 的边界定义是本文最大贡献。文中以“首次 prompt”为分界线。之前是 scaffolding（搭脚手架），之后是 harness（操控）。佳哥个人认为这个定义简洁有力，应该成为行业标准。</p><h3 id="tier-3-行业内高影响力文章" tabindex="-1">Tier 3: 行业内高影响力文章 <a class="header-anchor" href="#tier-3-行业内高影响力文章" aria-label="Permalink to &quot;Tier 3: 行业内高影响力文章&quot;">​</a></h3><ul><li><p>Simon Willison， <a href="https://simonwillison.net/guides/agentic-engineering-patterns/how-coding-agents-work/" target="_blank" rel="noreferrer">How Coding Agents Work</a>，提出 “Coding agent = harness for LLM” 的经典定义。</p></li><li><p>Inngest， <a href="https://www.inngest.com/blog/your-agent-needs-a-harness-not-a-framework" target="_blank" rel="noreferrer">Your Agent Needs a Harness, Not a Framework</a>，重点看 Harness vs Framework 的区分。</p></li><li><p>Swyx / Latent Space， <a href="https://www.latent.space/p/ainews-is-harness-engineering-real" target="_blank" rel="noreferrer">Is Harness Engineering Real?</a>，行业讨论，核心观点是“竞争优势在 Harness 而非Model”。</p></li><li><p>LangChain， <a href="https://github.com/langchain-ai/deepagents" target="_blank" rel="noreferrer">Deep Agents (GitHub)</a>，开源 Harness 实现，仅调 Harness 就让Terminal Bench 提升 13.7 分。</p></li><li><p>Lilian Weng， <a href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noreferrer">LLM Powered Autonomous Agents</a>，2023年的奠基综述，虽未用 “harness”一词但定义了同一架构。</p></li><li><p>Parallel.ai， <a href="https://parallel.ai/articles/what-is-an-agent-harness" target="_blank" rel="noreferrer">What is an Agent Harness</a>，最佳独立解释文，定义 Harness 6 大组件，区分 Harness/Framework/Orchestrator。</p></li></ul><p>欢迎你在留言区参与讨论，也推荐你把今天的内容，分享给身边关注 Harness 的朋友。</p>`,104)])])}const u=s(r,[["render",i]]);export{h as __pageData,u as default};
